findings-schema.text:
{
  "description": "One reader's findings: every claim carries the url it was read from.",
  "properties": {
    "findings": {
      "items": {
        "properties": {
          "claim": {
            "type": "string"
          },
          "provenance": {
            "type": "string"
          }
        },
        "required": [
          "claim",
          "provenance"
        ],
        "type": "object"
      },
      "type": "array"
    }
  },
  "required": [
    "findings"
  ],
  "type": "object"
}

findings-good.text:
{
  "findings": [
    {
      "claim": "logrotate-lite rotates on size, not on age",
      "provenance": "local://README.md"
    }
  ]
}

